namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Room { get; set; }
    public int DepartmentId { get; set; }
    public required Department Department { get; set; }
    public required Instructor Instructor { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
    public required string Description { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Bio { get; set; }
    public required string Email { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Study of literature, writing, and the English language." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events, societies, and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 40 papers in top-tier conferences and holds two patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Professor", Bio = "Dr. Martinez is an expert in abstract algebra and number theory with 20 years of teaching experience. He received the Distinguished Teaching Award in 2023.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Assistant Professor", Bio = "Dr. Johnson researches quantum computing and condensed matter physics. She joined the faculty after completing her postdoc at CERN.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Prof. James Wright", Title = "Professor", Bio = "Prof. Wright is a published novelist and literary critic specializing in 20th-century American fiction. His latest book was a finalist for the National Book Critics Circle Award.", Email = "jwright@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Lopez", Title = "Associate Professor", Bio = "Dr. Lopez is a historian focused on Latin American colonial history. She has conducted extensive archival research in Mexico, Peru, and Spain.", Email = "mlopez@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Professor", Bio = "Dr. Kim is a leading researcher in distributed systems and cloud computing. He has consulted for several Fortune 500 companies on scalable architectures.", Email = "dkim@university.edu" },
            new() { Id = 7, Name = "Dr. Emily Nguyen", Title = "Assistant Professor", Bio = "Dr. Nguyen specializes in statistical modeling and data analysis. Her research focuses on applications of Bayesian methods in the social sciences.", Email = "enguyen@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, algorithms, and data structures using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Tech Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Tech Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = false },
            new() { Id = 3, Code = "CS 420", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Hall 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 4, Code = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus: techniques of integration, sequences, series, and an introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Science Bldg 102", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 5, Code = "MATH 310", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of differential equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Science Bldg 204", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 6, Code = "MATH 340", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Science Bldg 108", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[6], IsFeatured = false },
            new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Physics Lab 101", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "PHYS 305", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, the Schrödinger equation, operators, angular momentum, and the hydrogen atom.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Room = "Physics Lab 210", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 9, Code = "ENG 102", Title = "Composition & Rhetoric", Description = "Development of academic writing skills with emphasis on argumentation, research methods, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 305", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 10, Code = "ENG 350", Title = "American Literature", Description = "Survey of major American literary works from the Colonial period to the present, with attention to historical and cultural contexts.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", Room = "Humanities 210", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 11, Code = "HIST 101", Title = "World History I", Description = "Survey of world civilizations from prehistory through the Renaissance, covering political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Humanities 112", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 12, Code = "HIST 260", Title = "History of Latin America", Description = "Exploration of Latin American history from pre-Columbian civilizations through independence movements and modern nation-building.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Room = "Humanities 118", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = true },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

