 @page "/enroll"
 @inject UniversityCourseCatalog.Services.CatalogService CatalogService
 @inject UniversityCourseCatalog.Services.EnrollmentService EnrollmentService

 <PageTitle>Enrollment Request</PageTitle>

 <h1>Enrollment Request</h1>
 <p>Fill out the form below to submit an enrollment request.</p>

 @if (Submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Request Submitted!</h4>
         <p>Your enrollment request has been received. You will be notified once it has been processed.</p>
         <hr />
         <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
     </div>
 }
 else
 {
     <div class="row">
         <div class="col-md-8 col-lg-6">
             <form method="post" @formname="enrollment">
                 <AntiforgeryToken />

                 <div class="mb-3">
                     <label for="name" class="form-label">Full Name</label>
                     <input type="text" class="form-control" id="name" name="Model.Name" value="@Model.Name" required />
                     @if (Errors.TryGetValue(nameof(Model.Name), out var nameError))
                     {
                         <div class="text-danger">@nameError</div>
                     }
                 </div>

                 <div class="mb-3">
                     <label for="studentId" class="form-label">Student ID</label>
                     <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required />
                     @if (Errors.TryGetValue(nameof(Model.StudentId), out var studentIdError))
                     {
                         <div class="text-danger">@studentIdError</div>
                     }
                 </div>

                 <div class="mb-3">
                     <label for="courseId" class="form-label">Course</label>
                     <select class="form-select" id="courseId" name="Model.CourseId" required>
                         <option value="">— Select a course —</option>
                         @foreach (var course in CatalogService.GetAllCourses())
                         {
                             <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code — @course.Title</option>
                         }
                     </select>
                     @if (Errors.TryGetValue(nameof(Model.CourseId), out var courseError))
                     {
                         <div class="text-danger">@courseError</div>
                     }
                 </div>

                 <button type="submit" class="btn btn-primary">Submit Request</button>
                 <a href="courses" class="btn btn-secondary ms-2">Cancel</a>
             </form>
         </div>
     </div>
 }

 @code {
     [SupplyParameterFromForm]
     public UniversityCourseCatalog.Models.EnrollmentRequest? Model { get; set; }

     [SupplyParameterFromQuery]
     public int? CourseId { get; set; }

     private bool Submitted { get; set; }
     private Dictionary<string, string> Errors { get; set; } = new();

     protected override void OnInitialized()
     {
         if (CourseId.HasValue && Model.CourseId == 0)
         {
             Model.CourseId = CourseId.Value;
         }
     }

     protected override void OnParametersSet()
     {
         if (HttpMethods.IsPost(HttpContext.Request.Method))
         {
             HandleSubmit();
         }
     }

     [CascadingParameter]
     public HttpContext HttpContext { get; set; } = default!;

     private void HandleSubmit()
     {
         Errors.Clear();

         var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
         var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
         if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
         {
             foreach (var result in validationResults)
             {
                 foreach (var memberName in result.MemberNames)
                 {
                     Errors[memberName] = result.ErrorMessage ?? "Invalid value.";
                 }
             }
             return;
         }

         EnrollmentService.Submit(Model);
         Submitted = true;
     }
 }

